import { CodeBlock } from "@/registry/erbium/blocks/code-block";
import { Field, FieldItem, FieldLabel } from "@/registry/erbium/ui/field";
import { RadioGroup, RadioGroupItem } from "@/registry/erbium/ui/radio-group";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import { useState } from "react";

const RadioGroupForm = () => {
  const [submitted, setSubmitted] = useState<string>();

  return (
    <form
      className="flex w-72 flex-col gap-group"
      onSubmit={(event) => {
        event.preventDefault();
        const data = Object.fromEntries(new FormData(event.currentTarget));
        setSubmitted(JSON.stringify(data, null, 2));
      }}
    >
      <Field>
        <RadioGroup name="shipping" required>
          <FieldItem orientation="horizontal">
            <RadioGroupItem value="standard" />
            <FieldLabel>Standard (5–7 days)</FieldLabel>
          </FieldItem>
          <FieldItem orientation="horizontal">
            <RadioGroupItem value="express" />
            <FieldLabel>Express (1–2 days)</FieldLabel>
          </FieldItem>
        </RadioGroup>
      </Field>
      <StatefulButton className="self-start" type="submit">
        Submit
      </StatefulButton>
      {submitted ? <CodeBlock code={submitted} language="json" title="Submitted values" /> : null}
    </form>
  );
};

export default RadioGroupForm;

import ExampleRadioGroupForm from "../examples/radio-group-form";

const Example = () => <ExampleRadioGroupForm />;

export default Example;
